關鍵程式包含伺服器端 GET Route Handler、網域 Allowlist 驗證與依據來源分類的 Parser：

```typescript
export async function GET(request: NextRequest) {
  const targetUrl = 'https://www.atmovies.com.tw/movie/new/';
  if (!isUrlAllowed(targetUrl)) {
    return NextResponse.json(loadMovieSnapshot('atmovies'), { status: 200 });
  }
  const res = await fetch(targetUrl, { signal: AbortSignal.timeout(8000) });
  const html = await res.text();
  const movies = parseAtMoviesNewHtml(html);
  return NextResponse.json({ movies, provenance });
}
```
